#include <iostream>
#include <vector>

class Pond {
public:
    void put(int w);

    int heaviest() const;

private:
    std::vector<int> weights;
};

void Pond::put(int w) {
    /* ① 把这一条放进 Pond 的水里 */
}

int Pond::heaviest() const {
    /* ② 一圈圈比过去，把最重的那条叼回来 */
    return 0;
}

int main() {
    int n = 0;
    std::cin >> n;
    Pond p;
    for (int i = 0; i < n; i++) {
        int w = 0;
        std::cin >> w;
        p.put(w);
    }
    std::cout << "最重的那条：" << p.heaviest() << " 克" << std::endl;
    return 0;
}

referenceSolutionTemplate:
#include <iostream>
#include <vector>

class Pond {
public:
    void put(int w);

    int heaviest() const;

private:
    std::vector<int> weights;
};

void Pond::put(int w) {
    weights.push_back(w);
}

int Pond::heaviest() const {
    int best = 0;
    for (int i = 0; i < static_cast<int>(weights.size()); i++) {
        if (weights[i] > best) {
            best = weights[i];
        }
    }
    return best;
}

int main() {
    int n = 0;
    std::cin >> n;
    Pond p;
    for (int i = 0; i < n; i++) {
        int w = 0;
        std::cin >> w;
        p.put(w);
    }
    std::cout << "最重的那条：" << p.heaviest() << " 克" << std::endl;
    return 0;
}

explanationTemplate:
两条正文的主意都不难，难的是**站在图纸外面说话要报家门**。

**① `put`：把货收进宅子。** 收一条，就是往宅子里那排格子末尾推一格：

```cpp
void Pond::put(int w) {
    weights.push_back(w);
}
```

`Pond::` 念作「**这是大宅子 `Pond` 名下**的招式」。报过家门之后，正文就算住在门外，摸宅子里的 `weights` 也是自家人摸自留地，翻译官喵放行。

**② `heaviest`：一圈比过去挑最重的。** 先立一个最重的位子（本喵从 0 起步 —— 货都是正数，不怕），一条条跟它比，比它重就换成记这条：

```cpp
int Pond::heaviest() const {
    int best = 0;
    for (int i = 0; i < static_cast<int>(weights.size()); i++) {
        if (weights[i] > best) {
            best = weights[i];
        }
    }
    return best;
}
```

⚠️ 三条记性念一遍：

1. **正文挪到图纸外面，门牌 `Pond::` 必须报** —— 少报一次就是 `non-member function` 那张脸；
2. **签名要和图纸里报名的那行一字不差**（`int`、`const`、名字、括号里的东西，全对上）；
3. **`main` 一个字都别动** —— 它是验收员，改验收员的眼睛可没用喵。
